CREATE TABLE projects(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,description text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 0,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plans(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),created_by uuid NOT NULL REFERENCES users(id),goal text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','cancelled')),steps jsonb NOT NULL DEFAULT '[]',planner_task_id uuid REFERENCES tasks(id),version integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE tasks ADD COLUMN project_id uuid REFERENCES projects(id), ADD COLUMN priority text NOT NULL DEFAULT 'normal' CHECK(priority IN('low','normal','high','urgent')), ADD COLUMN acceptance_criteria text NOT NULL DEFAULT '', ADD COLUMN plan_id uuid REFERENCES plans(id);
CREATE TABLE task_dependencies(task_id uuid NOT NULL REFERENCES tasks(id),depends_on uuid NOT NULL REFERENCES tasks(id),PRIMARY KEY(task_id,depends_on),CHECK(task_id<>depends_on));
CREATE TABLE task_attachments(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES tasks(id),name text NOT NULL,data bytea NOT NULL CHECK(octet_length(data)<=1048576),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE intelligence_grants(user_id uuid PRIMARY KEY REFERENCES users(id),granted_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX knowledge_search_idx ON knowledge USING gin(to_tsvector('simple',title||' '||content));
